import skarstrom as sk

sim = sk.Simulation.new()
sim.info.title = 'Ward 2022 - 50 ccm Flow Rate'
sim.info.description = 'CO2 breakthrough curve test based on Ward et al. 2022 for activated carbon in a lab-scale test rig. This is a binary CO2/Air breakthrough simulation where the bed is initially saturated with air and then fed with pure CO2. The adsorbent uses a dual-site Langmuir isotherm model and Haynes linear driving force model for mass transfer. The simulation includes coupled heat and mass transfer effects with wall heat transfer. Experimental breakthrough data is included and can be plotted to validate the solver performance. This configuration tests the low flow rate condition (50 ccm/min) of three flow rates studied.'
sim.info.author = 'Sam Affleck'

# ---- fluid --------------------------------------------------------------------
sim.add_component('CarbonDioxide')
sim.add_component('Air')
sim.fluid.adsorbed_heat_capacity_mode = 0
sim.fluid.heat_of_adsorption_convention = 0
sim.fluid.adsorbed_heat_capacity['CarbonDioxide'] = 36.96
sim.fluid.adsorbed_heat_capacity['Air'] = 0.0

# ---- adsorbents -----------------------------------------------------------------
ads_activated_carbon = sim.add_adsorbent('Activated Carbon', solid_density=799.0, heat_capacity=1040.0, thermal_conductivity=0.63, particle_void_fraction=0.0)
ads_activated_carbon.set_isotherm('dual_site_langmuir_c', {
    'CarbonDioxide': {'m1': 0.418, 'b1': 2.05e-06, 'q1': 29980.0, 'm2': 6.04, 'b2': 3.32e-06, 'q2': 20367.0},
}, components=['CarbonDioxide'])
ads_activated_carbon.set_isotherm('inert', components=['Air'])
ads_activated_carbon.set_rate_model('CarbonDioxide', 'ldf', 'haynes', tortuosity=3.0, macropore_void_fraction=0.59)
ads_activated_carbon.set_rate_model('Air', 'ldf', 'constant', k=0.0)
ads_activated_carbon.heat_of_adsorption['CarbonDioxide'] = 29980.0
ads_activated_carbon.heat_of_adsorption['Air'] = 0.0

# ---- column ----------------------------------------------------------------------
sim.bed.set_shape('cylinder', diameter=0.0189)
sim.bed.ambient_temperature = 291.4
sim.bed.set_thermal_equilibrium('lte')
sim.bed.set_particle_heat_transfer('constant', particle_htc=100.0)
sim.bed.bottom_void.enabled = False
sim.bed.bottom_void.volume = 0.0001
sim.bed.bottom_void.resistance_coefficient = 0.0
sim.bed.top_void.enabled = False
sim.bed.top_void.volume = 0.0001
sim.bed.top_void.resistance_coefficient = 0.0
sim.wall.set_material('ss316l', density=2700.0, heat_capacity=902.0, thermal_conductivity=205.0)
sim.wall.thickness = 0.00325
sim.wall.set_boundary('zero_flux')

# ---- layers (feed end first) ------------------------------------------------------
layer_activated_carbon = sim.add_layer('Activated Carbon', composition={'Activated Carbon': 1.0}, momentum='kozeny_carman', length=0.286, cells=60, bed_void_fraction=0.456, particle_diameter=0.003)
layer_activated_carbon.set_dispersion('ruthven', molecular_diffusion_coefficient=1.6e-05)
layer_activated_carbon.set_heat_dispersion('yagi_kunii')
layer_activated_carbon.set_internal_heat_transfer('constant', internal_htc=77.5)
layer_activated_carbon.set_external_heat_transfer('holman', holman_c=0.027, holman_m=0.8, holman_n=0.3333333333333333, external_velocity=0.5)

# ---- initial conditions --------------------------------------------------------
sim.initial_conditions.pressure = 100000.0
sim.initial_conditions.temperature = 291.4
sim.initial_conditions.wall_temperature = 291.4
sim.initial_conditions.velocity = 0.0
sim.initial_conditions.y['Air'] = 1.0
sim.initial_conditions.y['CarbonDioxide'] = 0.0

# ---- cycle -------------------------------------------------------------------------
sim.cycle.number_of_cycles = 1
sim.cycle.step_time_mode = 0
feed = sim.add_step('Feed', time=3000.0)
feed.bottom.set_streams('inlet', [
    sk.Stream('CO2 Inlet', flow=sk.volumetric_flow(8.333333333333335e-07), y={'Air': 0.0, 'CarbonDioxide': 1.0}, temperature=293.0),
])
feed.top.set_pressure('outlet', 100000.0, y={'CarbonDioxide': 0.0, 'Air': 1.0}, temperature=293.0)

# ---- solver, cyclic steady state, energy balance --------------------------------------
sim.settings.init_step = 1e-10
sim.settings.min_step = 1e-15
sim.settings.max_step = 0.0
sim.settings.reltol = 1e-06
sim.settings.nonlin_conv_coef = 0.1
sim.settings.max_order = 5
sim.settings.max_nonlin_iters = 15
sim.settings.max_conv_fails = 200
sim.settings.max_err_test_fails = 40
sim.settings.max_num_steps = 100000
sim.settings.max_iters_per_step = 50000
sim.settings.advection_scheme = 0
sim.settings.max_cycles_to_keep = 10
sim.settings.max_log_points_per_step = 200
sim.settings.acceleration_method = 0
sim.css.method = 0
sim.css.min_cycles = 5
sim.css.molar_absolute_tolerance = 0.0001
sim.css.molar_relative_tolerance = 0.0001
sim.css.mass_balance_tolerance = 0.005
sim.energy_balance.energy_balance_mode = 0
sim.energy_balance.isothermal_use_initial_temperature = True
sim.energy_balance.isothermal_temperature = 298.15


if __name__ == "__main__":
    import sys

    result = sim.run(cycles=int(sys.argv[1]) if len(sys.argv) > 1 else None)
    print(result.status, f"after {result.cycles_run} cycles")
    for k in sim.kpis(cycle=-1):
        print(f"{k.component}: purity {k.purity:.4f}, recovery {k.recovery:.4f}")
